import fs from "node:fs";
import path from "node:path";
import matter from "gray-matter";

/**
 * Validates that every content MDX file has parseable YAML frontmatter.
 *
 * Content is generated by the auto-news pipeline, so a single malformed
 * frontmatter block makes the whole site unbuildable: the deploy runs
 * scripts/build-search-index.js, which parses all files, and one bad file
 * fails the release. This turns that late, opaque release failure into an
 * early, actionable check that names the offending files.
 *
 * Also flags the double-escaped quote form ("\\\"") that ends a YAML
 * double-quoted scalar early, since that is the most common way this breaks.
 *
 * Exits non-zero when any file fails.
 */

const DIRS = ["news", "blog", "reviews", "ai-tools"];
const CONTENT_ROOT = "src/content";

const failures = [];
let scanned = 0;

for (const dir of DIRS) {
  const full = path.join(CONTENT_ROOT, dir);
  if (!fs.existsSync(full)) continue;

  for (const file of fs.readdirSync(full)) {
    if (!file.endsWith(".mdx")) continue;

    const rel = path.join(full, file);
    const raw = fs.readFileSync(rel, "utf8");
    scanned++;

    const fm = (raw.match(/^---\r?\n([\s\S]*?)\r?\n---/) || [])[1];
    if (fm === undefined) {
      failures.push({ rel, reason: "no frontmatter block" });
      continue;
    }

    if (/\\\\"/.test(fm)) {
      failures.push({
        rel,
        reason: 'double-escaped quote (\\\\") ends the YAML scalar early',
      });
      continue;
    }

    try {
      matter(`---\n${fm}\n---\n`);
    } catch (err) {
      failures.push({ rel, reason: err.reason || err.message });
    }
  }
}

if (failures.length) {
  console.error(`Invalid frontmatter in ${failures.length} of ${scanned} files:`);
  for (const f of failures) console.error(`  ${f.rel}: ${f.reason}`);
  process.exit(1);
}

console.log(`Frontmatter OK: ${scanned} files parsed`);